def shortest_tour(dist):
    n = len(dist)
    if n == 1:
        return 0
    INF = float('inf')
    dp = [[INF] * n for _ in range(1 << n)]
    dp[1][0] = 0
    for m in range(1, 1 << n, 2):
        row = dp[m]
        for u in range(n):
            du = row[u]
            if du == INF:
                continue
            for v in range(n):
                if not m >> v & 1:
                    nm = m | 1 << v
                    if du + dist[u][v] < dp[nm][v]:
                        dp[nm][v] = du + dist[u][v]
    return min(dp[-1][u] + dist[u][0] for u in range(n))

