int shortestTour(vector<vector<int>>& d) {
    int n = d.size(); if (n == 1) return 0; const int INF = 1e9; vector<vector<int>> dp(1 << n, vector<int>(n, INF)); dp[1][0] = 0;
    for (int m = 1; m < (1 << n); m += 2) for (int u = 0; u < n; u++) if (dp[m][u] < INF) for (int v = 0; v < n; v++) if (!(m >> v & 1)) dp[m | 1 << v][v] = min(dp[m | 1 << v][v], dp[m][u] + d[u][v]);
    int best = INF; for (int u = 0; u < n; u++) best = min(best, dp[(1 << n) - 1][u] + d[u][0]); return best;
}
